CREATE OR REPLACE FUNCTION accounts.create_studio(subject_id text, new_account uuid, at_time timestamp with time zone, defaults jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT FROM auth."user" WHERE id = subject_id AND "emailVerified") THEN
    RAISE EXCEPTION 'unverified subject';
  END IF;
  PERFORM set_config('aiuteur.account_id', new_account::text, true);
  INSERT INTO accounts.account VALUES (new_account, at_time);
  INSERT INTO accounts.settings VALUES (new_account, 'studio', 1, defaults);
  INSERT INTO auth.subject_map VALUES (subject_id, new_account);
  RETURN new_account;
END $function$

CREATE OR REPLACE FUNCTION accounts.job_extend(job uuid, token uuid, at_time timestamp with time zone, lease_ms integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE n integer;
BEGIN
  PERFORM set_config('aiuteur.claim', 'on', true);
  UPDATE accounts.job j SET
    lease_expires_at = at_time + make_interval(secs => lease_ms / 1000.0),
    due_at = LEAST(at_time + make_interval(secs => lease_ms / 1000.0), COALESCE(j.deadline_at, 'infinity')),
    updated_at = at_time
  WHERE j.job_id = job AND j.lease_token = token AND j.lease_expires_at > at_time AND j.due_at IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM set_config('aiuteur.claim', '', true);
  RETURN n = 1;
END $function$

CREATE OR REPLACE FUNCTION accounts.job_release(job uuid, token uuid, due timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE n integer;
BEGIN
  PERFORM set_config('aiuteur.claim', 'on', true);
  UPDATE accounts.job j SET lease_token = NULL, lease_expires_at = NULL, due_at = LEAST(due, COALESCE(j.deadline_at, 'infinity'))
  WHERE j.job_id = job AND j.lease_token = token AND j.due_at IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM set_config('aiuteur.claim', '', true);
  RETURN n = 1;
END $function$

CREATE OR REPLACE FUNCTION accounts.job_wake(job uuid, at_time timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE n integer;
BEGIN
  PERFORM set_config('aiuteur.claim', 'on', true);
  UPDATE accounts.job j SET due_at = LEAST(j.due_at, at_time)
  WHERE j.job_id = job AND j.due_at IS NOT NULL AND (j.lease_expires_at IS NULL OR j.lease_expires_at <= at_time);
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM set_config('aiuteur.claim', '', true);
  RETURN n = 1;
END $function$
